import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/TeFWiki%E3%81%A8%E3%82%B7%E3%82%A7%E3%83%AB%E3%82%B9%E3%82%AF%E3%83%AA%E3%83%97%E3%83%88.html","title":"TeFWikiとシェルスクリプト","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.68,"words":204},"filePathRelative":"TeFWikiとシェルスクリプト.md"}`),a={name:`TeFWikiとシェルスクリプト.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="tefwikiとシェルスクリプト" tabindex="-1"><a class="header-anchor" href="#tefwikiとシェルスクリプト"><span>TeFWikiとシェルスクリプト</span></a></h1><p><a href="./ボツエッセイ.html">ボツエッセイ</a>, <a href="./TeFWiki.html">TeFWiki</a>, <a href="./Unix的.html">Unix的</a></p><p>バックリンクを実装する時、TeFWikiに実装するのは気が乗らなかった(実装したけど)。 この気が乗らなさを考えてみたい。</p><p>シェルスクリプトで実装するのは凄くいい感じだ。 対話的に結果を試してみれるし、アプリなどに組込む作業などもいらない。 必要なコードを書いて結果を見る。 既存の何も変更しなくて良いし、使わなければ邪魔にもならない。</p><p>バックリンクを実装したが面倒だった。 UIのHTMLを変更しないといけないし、クライアントとサーバー側の通信も書かないといけないし、面倒だ。</p><p>一方でシェルスクリプトは使うのに面倒さはある。 いちいちターミナル開くのは面倒だし、コマンド名を思いだす必要もあるし、 時にはcdする必要もある。 ファイル名の絞り込み検索をコマンドラインで実装しているが、 これは結構体験が悪い。 他とぶつからないように名前を考えないといけないが、 これが思い出すのを面倒にもしている。</p><p>もっと現在ひらいているページでコマンドが実行出来る感じに出来ないかなぁ？ viでgrep実行する感じの快適さが欲しいなぁ。</p><p>現在開いている、という要素で必要なのは、以下だ。</p><ol><li>どのアプリにたいするものか、というコンテキスト</li><li>現在のディレクトリ</li><li>現在のファイル名</li></ol><p>コンテキストに限定したものであれば、findとかbackとかの名前が使える。</p><p>シェルスクリプトの良さはシェルスクリプトである必要は無いかもしれない。 アプリの既存の要素を邪魔しないreplであればいいのかもしれない。 VBScriptみたいな。</p><p>シェルスクリプトの良さのために必要な事を考える。</p><p>まず出力のターミナル的なものが欲しい。つまりprintをしていくだけで良い何か。</p><p>パイプ的に段階的に処理をしていきたい。</p><p>そしてアプリの構造に依存しないでやりとりしたい。 具体的には現在のディレクトリと現在のファイル名が変数とかで渡ってくる、とかそういう感じにしたい。</p><p>テキストのリストというインターフェースは優れていると思う。 そういう普遍的であまり変更が無いインターフェースでやりとりしたいよなぁ。</p><p>htmlの構造とかに影響を与えたくない。</p><p>プラグインではなく、なんかシェルスクリプト的なものを書いて、よければそれを使っていまいちならそのまま放置で良いような何かにしたいよなぁ。</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};